  const FOOD_SCORE = 10;
  const BONUS_SCORE = 30;
  const BONUS_EVERY = 5;     // bonus appears every N foods
  const BONUS_LIFE = 6000;   // ms

  // ---------- DOM ----------
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const el = id => document.getElementById(id);
  const scoreEl = el('score'), bestEl = el('best'), lenEl = el('len'),
        speedEl = el('speed'), eatenEl = el('eaten'), timeEl = el('time');
  const ovStart = el('ovStart'), ovPause = el('ovPause'), ovOver = el('ovOver');
  const ovScore = el('ovScore'), ovBest = el('ovBest'), ovMsg = el('ovMsg');
  const statusPill = el('statusPill'), statusText = el('statusText');
  const playLabel = el('playLabel'), playLabelM = el('playLabelM');

  // ---------- State ----------
  let cell = 20;
  let snake, dir, nextDir, food, bonus, bonusTimer;
  let score, best, eaten, foodsSinceBonus;
  let state = 'ready';       // ready | playing | paused | over
  let stepMs = BASE_MS;
  let acc = 0, last = 0, elapsed = 0;
  let particles = [];
  let foodPulse = 0;

  best = parseInt(localStorage.getItem('snake_best') || '0', 10) || 0;
  bestEl.textContent = best;

  // ---------- Canvas sizing ----------
  function resize(){
    const rect = canvas.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const size = Math.max(1, Math.floor(rect.width));
    canvas.width = size * dpr;
    canvas.height = size * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    cell = size / COLS;
  }
  window.addEventListener('resize', resize);

  // ---------- Helpers ----------
  const rand = n => Math.floor(Math.random() * n);
  function emptyCells(){
    const occ = new Set(snake.map(s => s.x + ',' + s.y));
    if (food) occ.add(food.x + ',' + food.y);
    if (bonus) occ.add(bonus.x + ',' + bonus.y);
    const out = [];
    for (let y = 0; y < ROWS; y++)
      for (let x = 0; x < COLS; x++)
        if (!occ.has(x + ',' + y)) out.push({x, y});
    return out;
  }
  function placeFood(){
    const cells = emptyCells();
    if (!cells.length) return null;
    return cells[rand(cells.length)];
  }

  // ---------- Game flow ----------
  function reset(){
    const cx = Math.floor(COLS / 2), cy = Math.floor(ROWS / 2);
    snake = [{x:cx-1,y:cy},{x:cx,y:cy},{x:cx+1,y:cy}];
    dir = {x:1,y:0};
    nextDir = {x:1,y:0};
    score = 0; eaten = 0; foodsSinceBonus = 0;
    stepMs = BASE_MS;
    bonus = null; bonusTimer = 0;
    particles = [];
    elapsed = 0; acc = 0;
    food = placeFood();
    updateHUD();
  }

  function start(){
    reset();
    state = 'playing';
    last = performance.now();
    showOverlay(null);
    setStatus('playing');
    setPlayLabel('暂停');
  }

  function pause(){
    if (state !== 'playing') return;
    state = 'paused';
    showOverlay('pause');
    setStatus('paused');
    setPlayLabel('继续');
  }

  function resume(){
    if (state !== 'paused') return;
    state = 'playing';
    last = performance.now();
    showOverlay(null);
    setStatus('playing');
    setPlayLabel('暂停');
  }

  function togglePlay(){
    if (state === 'ready' || state === 'over') start();
    else if (state === 'playing') pause();
    else if (state === 'paused') resume();
  }

  function gameOver(){
    state = 'over';
    if (score > best){
      best = score;
      localStorage.setItem('snake_best', String(best));
      bestEl.textContent = best;
      ovMsg.textContent = '🎉 新纪录！你刷新了最高分！';
    } else {
      ovMsg.textContent = '不错的表现，再来一局？';
    }
    ovScore.textContent = score;
    ovBest.textContent = best;
    showOverlay('over');
    setStatus('over');
    setPlayLabel('开始');
    // death burst
    const head = snake[0];
    burst(head.x, head.y, '#ff6b5c', 26);
  }

  // ---------- Step ----------
  function step(){
    dir = nextDir;
    const head = {x: snake[0].x + dir.x, y: snake[0].y + dir.y};

    // wall
    if (head.x < 0 || head.x >= COLS || head.y < 0 || head.y >= ROWS){
      gameOver(); return;
    }
    // self (tail cell will move unless we grow, so ignore last segment when not eating)
    const willEat = (food && head.x === food.x && head.y === food.y) ||
                    (bonus && head.x === bonus.x && head.y === bonus.y);
    const body = willEat ? snake : snake.slice(0, -1);
    for (const s of body){
      if (s.x === head.x && s.y === head.y){ gameOver(); return; }
    }

    snake.unshift(head);

    if (food && head.x === food.x && head.y === food.y){
      score += FOOD_SCORE;
      eaten++;
      foodsSinceBonus++;
      stepMs = Math.max(MIN_MS, stepMs - SPEED_STEP);
      burst(head.x, head.y, '#ffb43d', 16);
      bumpScore();
      food = placeFood();
      if (foodsSinceBonus >= BONUS_EVERY){
        foodsSinceBonus = 0;
        spawnBonus();
      }
    } else if (bonus && head.x === bonus.x && head.y === bonus.y){
      score += BONUS_SCORE;
      burst(head.x, head.y, '#4fd6c4', 22);
      bumpScore();
      bonus = null; bonusTimer = 0;
    } else {
      snake.pop();
    }

    updateHUD();
  }

  function spawnBonus(){
    const cells = emptyCells();
    if (!cells.length) return;
    bonus = cells[rand(cells.length)];
    bonusTimer = BONUS_LIFE;
  }

  // ---------- Particles ----------
  function burst(gx, gy, color, n){
    const px = (gx + 0.5) * cell, py = (gy + 0.5) * cell;
    for (let i = 0; i < n; i++){
      const a = Math.random() * Math.PI * 2;
      const sp = (Math.random() * 0.14 + 0.04) * cell;
      particles.push({
        x: px, y: py,
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
        life: 1, decay: 0.02 + Math.random() * 0.02,
        size: (Math.random() * 0.28 + 0.14) * cell,
        color
      });
    }
  }
  function updateParticles(dt){
    const f = dt / 16.67;
    for (let i = particles.length - 1; i >= 0; i--){
      const p = particles[i];
      p.x += p.vx * f; p.y += p.vy * f;
      p.vx *= 0.94; p.vy *= 0.94;
      p.life -= p.decay * f;
      if (p.life <= 0) particles.splice(i, 1);
    }
  }

  // ---------- Render ----------
  function roundRect(x, y, w, h, r){
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  function draw(){
    const W = canvas.width / (Math.min(window.devicePixelRatio || 1, 2));
    const H = canvas.height / (Math.min(window.devicePixelRatio || 1, 2));
    ctx.clearRect(0, 0, W, H);

    // board bg
    const bg = ctx.createLinearGradient(0, 0, W, H);
    bg.addColorStop(0, '#0a1c14');
    bg.addColorStop(1, '#07130d');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);

    // checkerboard
    for (let y = 0; y < ROWS; y++){
      for (let x = 0; x < COLS; x++){
        if ((x + y) % 2 === 0){
          ctx.fillStyle = 'rgba(120,220,170,0.035)';
          ctx.fillRect(x * cell, y * cell, cell, cell);
        }
      }
    }

    // subtle grid lines
    ctx.strokeStyle = 'rgba(120,220,170,0.05)';
    ctx.lineWidth = 1;
    for (let i = 1; i < COLS; i++){
      ctx.beginPath(); ctx.moveTo(i * cell, 0); ctx.lineTo(i * cell, H); ctx.stroke();
    }
    for (let i = 1; i < ROWS; i++){
      ctx.beginPath(); ctx.moveTo(0, i * cell); ctx.lineTo(W, i * cell); ctx.stroke();
    }

    // food
    if (food) drawFood(food.x, food.y);
    // bonus
    if (bonus) drawBonus(bonus.x, bonus.y);

    // snake
    drawSnake();

    // particles
    for (const p of particles){
      ctx.globalAlpha = Math.max(0, p.life);
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  function drawFood(gx, gy){
    const cx = (gx + 0.5) * cell, cy = (gy + 0.5) * cell;
    const r = cell * 0.34 * (1 + Math.sin(foodPulse) * 0.08);
    // glow
    const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, r * 2.4);
    g.addColorStop(0, 'rgba(255,180,61,0.5)');
    g.addColorStop(1, 'rgba(255,180,61,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(cx, cy, r * 2.4, 0, Math.PI * 2); ctx.fill();
    // body
    const body = ctx.createRadialGradient(cx - r*0.3, cy - r*0.3, r*0.1, cx, cy, r);
    body.addColorStop(0, '#ffd27a');
    body.addColorStop(1, '#ff9d2e');
    ctx.fillStyle = body;
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.fill();
    // leaf
    ctx.fillStyle = '#3ee08a';
    ctx.beginPath();
    ctx.ellipse(cx + r*0.35, cy - r*0.95, r*0.32, r*0.18, -0.6, 0, Math.PI*2);
    ctx.fill();
    // shine
    ctx.fillStyle = 'rgba(255,255,255,0.55)';
    ctx.beginPath(); ctx.arc(cx - r*0.3, cy - r*0.3, r*0.18, 0, Math.PI*2); ctx.fill();
  }

  function drawBonus(gx, gy){
    const cx = (gx + 0.5) * cell, cy = (gy + 0.5) * cell;
    const frac = bonusTimer / BONUS_LIFE;
    const r = cell * 0.34;
    // glow
    const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, r * 2.6);
    g.addColorStop(0, 'rgba(79,214,196,0.55)');
    g.addColorStop(1, 'rgba(79,214,196,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(cx, cy, r * 2.6, 0, Math.PI * 2); ctx.fill();
    // star
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(performance.now() / 500);
    ctx.fillStyle = '#eafffb';
    ctx.beginPath();
    const spikes = 5, outer = r * 1.15, inner = r * 0.5;
    for (let i = 0; i < spikes * 2; i++){
      const rad = i % 2 === 0 ? outer : inner;
      const a = (i / (spikes * 2)) * Math.PI * 2 - Math.PI / 2;
      const px = Math.cos(a) * rad, py = Math.sin(a) * rad;
      i === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
    }
    ctx.closePath(); ctx.fill();
    ctx.restore();
    // timer ring
    ctx.strokeStyle = 'rgba(79,214,196,0.9)';
    ctx.lineWidth = Math.max(2, cell * 0.08);
    ctx.beginPath();
    ctx.arc(cx, cy, r * 1.5, -Math.PI/2, -Math.PI/2 + frac * Math.PI * 2);
    ctx.stroke();
  }

  function drawSnake(){
    const n = snake.length;
    // body segments (draw tail -> head so head is on top)
    for (let i = n - 1; i >= 1; i--){
      const s = snake[i];
      const t = i / Math.max(1, n - 1);
      const pad = cell * (0.08 + t * 0.06);
      const x = s.x * cell + pad, y = s.y * cell + pad;
      const w = cell - pad * 2, h = cell - pad * 2;
      const r = cell * 0.32;
      // color gradient head->tail
      const light = 1 - t * 0.55;
      const col = `rgb(${Math.round(62*light+10)},${Math.round(224*light+10)},${Math.round(138*light+10)})`;
      ctx.fillStyle = col;
      roundRect(x, y, w, h, r);
      ctx.fill();
      // subtle top highlight
      ctx.fillStyle = 'rgba(255,255,255,0.06)';
      roundRect(x, y, w, h * 0.4, r);
      ctx.fill();
    }

    // head
    const head = snake[0];
    const pad = cell * 0.06;
    const x = head.x * cell + pad, y = head.y * cell + pad;
    const w = cell - pad * 2, h = cell - pad * 2;
    const hg = ctx.createLinearGradient(x, y, x, y + h);
    hg.addColorStop(0, '#5cf0a0');
    hg.addColorStop(1, '#25b56f');
    ctx.fillStyle = hg;
    roundRect(x, y, w, h, cell * 0.34);
    ctx.fill();
    // glow
    ctx.save();
    ctx.shadowColor = 'rgba(62,224,138,0.6)';
    ctx.shadowBlur = cell * 0.5;
    ctx.fillStyle = 'rgba(62,224,138,0.15)';
    roundRect(x, y, w, h, cell * 0.34);
    ctx.fill();
    ctx.restore();

    // eyes
    const cx = head.x * cell + cell/2, cy = head.y * cell + cell/2;
    const ex = dir.x, ey = dir.y;
    const perpX = -ey, perpY = ex;
    const eo = cell * 0.16, fo = cell * 0.14;
    const eyeR = cell * 0.11, pupR = cell * 0.055;
    for (const side of [-1, 1]){
      const exx = cx + ex*fo + perpX*eo*side;
      const eyy = cy + ey*fo + perpY*eo*side;
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.arc(exx, eyy, eyeR, 0, Math.PI*2); ctx.fill();
      ctx.fillStyle = '#04140c';
      ctx.beginPath(); ctx.arc(exx + ex*eyeR*0.35, eyy + ey*eyeR*0.35, pupR, 0, Math.PI*2); ctx.fill();
    }
    // tongue flick
    const flick = (Math.sin(performance.now()/120) > 0.4);
    if (flick){
      const tx = cx + ex * cell * 0.5, ty = cy + ey * cell * 0.5;
      ctx.strokeStyle = '#ff6b5c';
      ctx.lineWidth = Math.max(1.5, cell * 0.06);
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(cx + ex*cell*0.3, cy + ey*cell*0.3);
      ctx.lineTo(tx, ty);
      ctx.stroke();
      const split = cell * 0.12;
      ctx.beginPath();
      ctx.moveTo(tx, ty);
      ctx.lineTo(tx + (ex*0.5 - perpX*0.5)*split, ty + (ey*0.5 - perpY*0.5)*split);
      ctx.moveTo(tx, ty);
      ctx.lineTo(tx + (ex*0.5 + perpX*0.5)*split, ty + (ey*0.5 + perpY*0.5)*split);
      ctx.stroke();
    }
  }

  // ---------- HUD ----------
  function updateHUD(){
    scoreEl.textContent = score;
    lenEl.textContent = snake.length;
    eatenEl.textContent = eaten;
    speedEl.textContent = (BASE_MS / stepMs).toFixed(1) + '×';
  }
  function bumpScore(){
    scoreEl.classList.remove('bump');
    void scoreEl.offsetWidth;
    scoreEl.classList.add('bump');
  }
  function fmtTime(ms){
    const s = Math.floor(ms / 1000);
    const m = Math.floor(s / 60);
    return m + ':' + String(s % 60).padStart(2, '0');
  }
  function setStatus(s){
    statusPill.dataset.state = s;
    const map = {ready:'准备就绪', playing:'进行中', paused:'已暂停', over:'已结束'};
    statusText.textContent = map[s];
  }
  function setPlayLabel(t){
    playLabel.textContent = t;
    playLabelM.textContent = t;
  }
  function showOverlay(which){
    ovStart.classList.toggle('hidden', which !== 'start');
    ovPause.classList.toggle('hidden', which !== 'pause');
    ovOver.classList.toggle('hidden', which !== 'over');
  }

  // ---------- Loop ----------
  function loop(now){
    const dt = Math.min(100, now - last);
    last = now;

    if (state === 'playing'){
      elapsed += dt;
      timeEl.textContent = fmtTime(elapsed);
      if (bonus){
        bonusTimer -= dt;
        if (bonusTimer <= 0){ bonus = null; bonusTimer = 0; }
      }
      acc += dt;
      let guard = 0;
      while (acc >= stepMs && state === 'playing' && guard < 8){
        step();
        acc -= stepMs;
        guard++;
      }
    }

    foodPulse += dt * 0.006;
    updateParticles(dt);
    draw();
    requestAnimationFrame(loop);
  }

  // ---------- Input ----------
  function setDir(x, y){
    // prevent reversing into self
    if (x === -dir.x && y === -dir.y) return;
    nextDir = {x, y};
  }
  const DIRS = {
    up:{x:0,y:-1}, down:{x:0,y:1}, left:{x:-1,y:0}, right:{x:1,y:0}
  };

  window.addEventListener('keydown', e => {
    const k = e.key;
    if (k === 'ArrowUp' || k === 'w' || k === 'W'){ e.preventDefault(); if (state==='ready'||state==='over') start(); setDir(0,-1); }
    else if (k === 'ArrowDown' || k === 's' || k === 'S'){ e.preventDefault(); if (state==='ready'||state==='over') start(); setDir(0,1); }
    else if (k === 'ArrowLeft' || k === 'a' || k === 'A'){ e.preventDefault(); if (state==='ready'||state==='over') start(); setDir(-1,0); }
    else if (k === 'ArrowRight' || k === 'd' || k === 'D'){ e.preventDefault(); if (state==='ready'||state==='over') start(); setDir(1,0); }
    else if (k === ' ' || k === 'Spacebar'){ e.preventDefault(); togglePlay(); }
    else if (k === 'r' || k === 'R'){ e.preventDefault(); start(); }
    else if (k === 'Enter'){ e.preventDefault(); if (state==='ready'||state==='over') start(); }
  });

  // buttons
  el('btnStart').addEventListener('click', start);
  el('btnResume').addEventListener('click', resume);
  el('btnRestart2').addEventListener('click', start);
  el('btnAgain').addEventListener('click', start);
  el('btnPlay').addEventListener('click', togglePlay);
  el('btnPlayM').addEventListener('click', togglePlay);
  el('btnReset').addEventListener('click', start);
  el('btnResetM').addEventListener('click', start);

  // d-pad
  document.querySelectorAll('.dpad button[data-dir]').forEach(btn => {
    const go = e => {
      e.preventDefault();
      const d = DIRS[btn.dataset.dir];
      if (state === 'ready' || state === 'over') start();
      setDir(d.x, d.y);
    };
    btn.addEventListener('touchstart', go, {passive:false});
    btn.addEventListener('mousedown', go);
  });

  // swipe on board
  let touchStart = null;
  const board = document.querySelector('.board');
  board.addEventListener('touchstart', e => {
    const t = e.touches[0];
    touchStart = {x: t.clientX, y: t.clientY};
  }, {passive:true});
  board.addEventListener('touchend', e => {
    if (!touchStart) return;
    const t = e.changedTouches[0];
    const dx = t.clientX - touchStart.x, dy = t.clientY - touchStart.y;
    if (Math.abs(dx) < 24 && Math.abs(dy) < 24){ touchStart = null; return; }
    if (Math.abs(dx) > Math.abs(dy)) setDir(dx > 0 ? 1 : -1, 0);
    else setDir(0, dy > 0 ? 1 : -1);
    touchStart = null;
  }, {passive:true});

  // ---------- Init ----------
  reset();
  resize();
  showOverlay('start');
  setStatus('ready');
  setPlayLabel('开始');
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
